from probe import probe_backend
from registry import register_tools

def scenario(data):
    ready_after = data.get('backend_ready_after_attempts', 0)
    max_attempts = data.get('max_attempts', 1)
    tools = data.get('tools', [])
    ready = probe_backend(ready_after, 1)
    if not ready:
        return {
            'status': 'degraded',
            'attempts': 1,
            'registered_tools': [],
            'diagnostics': ['backend not ready on first probe']
        }
    return {
        'status': 'registered',
        'attempts': 1,
        'registered_tools': register_tools(tools),
        'diagnostics': []
    }
